 for (const [klass, name] of [[HTMLScriptElement,'src'],[HTMLLinkElement,'href']]) {
  const prop=Object.getOwnPropertyDescriptor(klass.prototype,name);
  Object.defineProperty(klass.prototype,name,{...prop,set(value){prop.set.call(this,resources[value]||value);}});
 }

 const open = XMLHttpRequest.prototype.open;
 XMLHttpRequest.prototype.open = function(method, url, ...args) {
  if (typeof url === 'string' && /https?:\/\/store\d?\.tildaapi\.[^/]+\/api\//.test(url)) {
   const u = new URL(url);
   url = '/api/catalog?operation=' + encodeURIComponent(u.pathname.split('/')[2]) + '&' + u.search.slice(1);
  }
  return open.call(this, method, url, ...args);
 };
